const DEFAULT_BLIND_TYPE = 1

export function getMttBlindLevels(blindType: number | undefined | null): MttBlindLevelValue[] {
  const normalized = Number.isFinite(Number(blindType)) ? Number(blindType) : DEFAULT_BLIND_TYPE
  return MTT_BLIND_TABLES[normalized] ?? MTT_BLIND_TABLES[DEFAULT_BLIND_TYPE] ?? []
}

export function getMttBlindLevelValue(
  blindType: number | undefined | null,
  levelZeroBased: number,
): MttBlindLevelValue | null {
  const list = getMttBlindLevels(blindType)
  if (levelZeroBased < 0 || levelZeroBased >= list.length) return null
  return list[levelZeroBased] ?? null
}
